package in.tucor.api.buyer;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.util.*;public interface BuyerBankAccountRepository extends JpaRepository<BuyerBankAccount,UUID>{List<BuyerBankAccount> findByBuyerIdOrderByCreatedAtAsc(UUID buyerId);Optional<BuyerBankAccount> findByIdAndBuyerId(UUID id,UUID buyerId);boolean existsByBuyerIdAndAccountNumber(UUID buyerId,String accountNumber);@Modifying(clearAutomatically=true,flushAutomatically=true) @Query("update BuyerBankAccount b set b.primary=false where b.buyerId=:buyerId and b.primary=true")int clearPrimary(@Param("buyerId") UUID buyerId);}
